local entities: { [string]: string } = {}
for name, first, second in string.gmatch(PACKED, "(%w+) (%x+) ?(%x*)\n") do
	local codePoint = tonumber(first, 16) :: number
	entities[name] = if second == "" then utf8.char(codePoint) else utf8.char(codePoint, tonumber(second, 16) :: number)
end

return entities
